L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "아직도 선명해. 결단하지 못한 아이들이 실험실에서 어떻게 됐는지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "m_bTalkCenterFadeIn"
L48_1[L49_1] = true
L49_1 = "まだ鮮明に浮かぶ。決断できなかった子たちが実験室でどうなったのか。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "It's still vivid. What happened to the kids who couldn't decide in the lab."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我還記得很清楚，那些沒能做出決斷的孩子在實驗室裡怎麼樣了。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "It's still vivid. What happened to the kids who couldn't decide in the lab."
L48_1.m_Talk_DEU = L49_1
L49_1 = "It's still vivid. What happened to the kids who couldn't decide in the lab."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "OMEN_CHAMBER_INTERLUDE7@101#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L49_1.m_CutScenProcessKey = 0
L49_1.m_CutScenID = 7900114
L49_1.m_CutScenStrID = "OMEN_CHAMBER_INTERLUDE7"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "목줄 안에서 쇳조각이 나오는 건 물론, 어떤 애는 잘린 팔을 무기처럼 썼다니까?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "m_bTalkCenterFadeIn"
L49_1[L50_1] = true
L50_1 = "首輪の内側からくさびが出てくるのなんて普通にあったし、切り落とされた自分の腕を武器のように使ってた子もいたなぁ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "When they resisted, shards erupted from the collars and dug into their necks. Some even used severed arms like weapons."
L49_1.m_Talk_ENG = L50_1
L50_1 = "不只是項圈裡面會冒出鐵塊，還有孩子把被砍斷的手臂拿來當武器用。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "When they resisted, shards erupted from the collars and dug into their necks. Some even used severed arms like weapons."
L49_1.m_Talk_DEU = L50_1
L50_1 = "When they resisted, shards erupted from the collars and dug into their necks. Some even used severed arms like weapons."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "OMEN_CHAMBER_INTERLUDE7@102#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L50_1.m_CutScenProcessKey = 0
L50_1.m_CutScenID = 7900114
L50_1.m_CutScenStrID = "OMEN_CHAMBER_INTERLUDE7"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "그걸로 폐쇄된 실험실의 문을 박박 긁는데… 왜 그렇게 미련한 짓을 하나 싶더라."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "m_bTalkCenterFadeIn"
L50_1[L51_1] = true
L51_1 = "それで閉鎖された実験室のドアを引っ掻きまくって……なんてバカなことをするんだろうって思ったっけ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "They scraped the sealed lab door with them... I wondered why they were being so foolish."
L50_1.m_Talk_ENG = L51_1
L51_1 = "用那個不停刮著實驗室封閉的門…我還心想他們為什麼要做這麼愚蠢的事。"
